import sys

def check_bidirectional(graph):
    visited = [False] * len(graph)
    starts = [i for i, j in graph if j == 1]
    for start in starts:
        if not visited[start]:
            stack = [start]
            visited[start] = True
            while stack:
                vertex = stack.pop()
                for neighbor in graph[vertex]:
                    if not visited[neighbor]:
                        graph[neighbor][vertex] = 1  # Mark edge as bidirectional
                        visited[neighbor] = True
                        stack.append(neighbor)
    return graph

def can_assign(graph, a):
    assign = {i: 0 for i in range(1, len(graph)+1)}
    reverse_graph = {vertex: [] for vertex in range(1, len(graph)+1)}
    for vertex in range(1, len(graph)+1):
        for i in range(len(graph[vertex])):
            if graph[vertex][i] == 1:
                reverse_graph[vertex].append(vertex - 1)
    assigned = set()
    for i in range(len(graph)):
        if len(assigned) >= a[i]:
            continue
        if a[i] not in assigned:
            for j in range(len(graph[i])):
                if a[i] != graph[i][j]:
                    if j >= len(graph) or i != graph[j][j]:
                        return False
                    if graph[j][j] == 1:
                        continue
                    reverse_graph[i][j] = 0
                    assign[graph[j][j]] = a[i]
                    assigned.add(a[i])
    return True

def main():
    num = int(sys.stdin.readline())
    graph = [[] for _ in range(num+1)]
    for line in sys.stdin:
        arr = list(map(int, line.strip().split()))
        graph[arr[0]].append(arr[1]-1)
    for i in range(1, len(graph)): graph[i].append(1)
    reverse_graph = check_bidirectional(graph)
    a = [int(x) for x in sys.stdin.readline().strip().split()]
    if can_assign(reverse_graph, a): print("POSSIBLE")
    else: print("IMPOSSIBLE")

if __name__ == "__main__":
    main()
