import sys

class Game:
    def __init__(self, n):
        self.n = n
        self.hats = [0] * n
        self.helix = [0]

    def nth_solution(self, n):
        h = [(i + 1 if i % 2 == 0 else 0) for i in range(1, n + 1)]
        self.helix = h
        for i in range(n - 1):
            if h[i+1] == 1 and h[i] == 0:
                for j in range(i, i - (self.helix[i] + 1), -1):
                    if self.helix[j] != 1:
                        self.helix[j] += 1
        for i in range(self.n):
            self.hats[i] = h[i]
        return ''.join(map(str, self.hats))

