    for i, y in enumerate(q):
        parent_class = y
        for j in range(1, y + 1):
            tree[j][y] = tree[j - 1][y]

        tree[j][i] = -1  # Mark this class as the root of its own subtree
        for diff in range(1, min(q) + 1):
            if i + diff < max(q):
                tree[j + diff][i + diff] = tree[j][i + diff]
                tree[i + diff][j + diff] = tree[j][i]

    # Function to calculate the number of classes that can change to y with distance exactly d
    def tally(tree, start, d):
        count = 0
        stack = [start]

        while stack:
            current = stack.pop()

            if tree[current][d] == -1:  # Check if there exists a path of length d to y
                count += 1

            for diff in range(1, q) if d == 0 else range(1, min(q) + 1):
                if tree[current][diff] != -1:
                    stack.append(tree[current][diff])

        return count

    # Output the results for each level
    for i in range(m):
        print(tally(tree, q[i], 0), end=' ')
        if i < m - 1:
            print(end='\n')

