    # Initialize the cell values with a sequence that repeats a certain number of times within the height 'h'
    sequence = set()
    for y in range(1, h+1):
        if y % h == 0:
            for x in range(1, len(sequence)+1):
                # Add sequence from the previous chunk
                value = (len(sequence) // h) * x + y // h
                sequence.add(value)
        else:
            for x in range(1, h+1):
                if x - (h - y) // h < 0:
                    break
                value = (len(sequence) // h)*h + (h - y) // h * x + y % h + 1
                sequence.add(value)

    # Check if all cells in rectangles of height 'h' and width 'w' are the same
    for j in range(w):
        for i in range(h):
            value = sequence[i * h + j]
            for j2 in range(j, w):
                if value != sequence[i * h + j2]:
                    return 0  # Rectangles have different values

    return 1  # All cells have the same value

