from math import gcd
from functools import lru_cache

# Function to compute (a + b) % p
def eor(a, b, p):
    return (a + b) % p

# Function to compute the greatest common divisor of a and b
def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)

# Function to get the modular multiplicative inverse of b under modulo p
def modinv(b, p):
    return pow(b, p - 2, p)

# Function to compute n raised to the power of m (mod p)
@lru_cache(maxsize=None)
def power(n, m, p):
    if m == 1:
        return n % p
    elif m % 2 == 0:
        return eor(power(eor(n, n, p), m // 2, p), 1, p)
    else:
        return eor(n, power(eor(n, n, p), (m - 1) // 2, p), p)

# Function to compute the number of compatible pairs for a given array length
def compatible_pairs(n):
    if n < 6:
        return power(1 + n, (9**n - 9) // 6, 998244353)
    else:
        return (power(1 + n, (2*(9**(n - 1)) - 19*9**((n - 2) // 2) - 5) // 28, 998244353) - pow(2*(4*9**((n - 1) // 2) + 4*281*(n // 16)), 1, 998244353) + 4*9**((n // 2) % 4)) % 998244353

# Read input
n, k = map(int, input().split())

# Compute result
