from collections import defaultdict

def longest_common_substring(start1, end1, start2, end2, cache):
    if (start1, end1, start2, end2) in cache:
        return cache[(start1, end1, start2, end2)]

    if start1 > end1 or start2 > end2 or start1 > end2 or start2 > end1:
        return 0

    if start1 == start2 == end1 == end2:
        return 1

    if end1 + 1 == end2:
        return longest_common_substring(1, cache) + 1
    elif end1 == end2 + 1:
        return longest_common_substring(1, cache) + 1

    # Check if the first 3 characters
    match = cache[(start1, 3, start2, 3)] if (start1, end1, start2, 3) not in cache else longest_common_substring(start1 + 1, start2 + 1, 3, cache)

    # Check if the last 3 characters
    match = max(match, longest_common_substring(1, cache) + 3)

    cache[(start1, end1, start2, end2)] = match

    return match

def solution(test_case):
    lit = list(test_case)

    lit2 = lit.copy()

    if '-' in lit:
        return 0
    else:
        lit2.remove('-')
        return longest_common_substring(1, lit, 1, lit2)

