import sys

def find_permutation(points_str, s_str):
    points = []
    for i in range(3, len(points_str)):
        points.append((int(points_str[i-2]), int(points_str[i-1])))

    for i in range(3, len(s_str)+2):
        points.append(points[i-2] if s_str[(i)%len(s_str)] == "L" else points[i-1])

    solutions = []
    for perm in permutations(range(1, len(points)+1)):
        valid = True
        prev = None
        for i in range(1, len(points)):
            if points[perm[i-1]] == prev:
                valid = False
                break
            x1, y1 = points[perm[i-1]]
            x2, y2 = points[perm[i]]
            if x1 < x2 > x1 or y1 < y2:  # Vertical (clockwise or counterclockwise)
                valid = False
                break
            else:
                prev = (x1, y1)
        if not valid:
            break
        solutions.append(perm)

    return solutions[0] if solutions else -1

def permutations(n):
    if n == 1:
        yield (n,)
    else:
        for prev in permutations(n-1):
            for position in range(n):
                if position not in prev:
                    yield prev[:n] + (position,)

