from collections import deque

def adjust(idx):
    return (idx[0], idx[1])

def find_tail_coordinate(pre_tail, cur, pd):
    current_pos = pd[cur][pre_tail[0] % len(pd[cur])]
    if current_pos in pd[cur][-len(pd[cur]):]: 
        return max(pd[cur][-len(pd[cur]):])
    else:
        return min(pd[cur][:len(pd[cur])])

def rec(x, y, pd):
    if pd[x][y] != 0:
        return 0
    current_color = pd[x][y]
    pre_tail = [x, y]
    mid_idx = deque()
    pd[x][y] = 0
    try:
        while True:
            tail_x, tail_y = adjust(pre_tail)
            mid_idx.appendleft((tail_x, tail_y))
            pd[tail_x][tail_y] = 0
            nxt_tail_x, nxt_tail_y = adjust(tail_x, tail_y + 1)
            pd[nxt_tail_x][nxt_tail_y] = current_color
            pre_tail = (tail_x, tail_y + 1)
    except OutOfBoundsError:
        pass
    mid_idx_pows = pow(len(pd[yy]) - len(mid_idx), y)
    mid_idx = pd[::-1]
    if mid_idx_pows != 0:
        while pd[x][y] == 0:
            pd[x][y] = current_color
            idx = mid_idx[pow(len(pd[yy]) - len(mid_idx), y)]
            tx, ty = find_tail_coordinate((x, y), idx[1], pd)
            pd[tx][ty] = 0
            pd[tx][ty] = current_color
            nx, ny = adjust((tx - 1, ty - 1), (tx, ty))
            pd[nx][ny] = 0
            pd[nx][ny] = current_color
            x, y = nx - 1, ny - 1
    return mid_idx_pows

