def find_max LCS_length(text1, text2, l1, r1, l2, r2):
    # Function to find the length of the longest matching substring
    def matching_length(s1, s2):
        m, n = len(s1), len(s2)
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        max_length = 0
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if s1[i - 1] == s2[j - 1]:
                    dp[i][j] = dp[i-1][j-1] + 1
                    max_length = max(max_length, dp[i][j])
        return max_length
    # Find the lengths of the matched substrings for both texts
    min_length = min(r1 - l1 + 1, r2 - l2 + 1)
    left, right = max(min(min(r1 - 1, r2 - 1), r1 + l1 - 1, r2 + l2 - 1), l1), min(left + min_length - 1, r2)
    end = 2 * left + 1
    end_idx = left + min_length - 1
    if end_idx > right:
        return 0
    left, right = l2, r2
    mid = (right - left) // 2
    p1, p2 = l1 + mid - 1, right + mid - 1
    # First left-most indices
    if left - 1 >= 0 and text1[left - 1] == text2[p1]:
        if p1 + left - 1 < right:
            left -= 1
        else:
            mid = 0
    elif right + 1 < len(text1):
        if right < mid + 1 and len(text1[: mid + 1]) & 1 == 0:
            mid += 1
    # First right-most indices
    if p2 > len(text2) - mid - 1:
        p2 -= 1
        right += mid
    # Only do the iteration if the above is done, the last iteration can handle it.
    while left -1 >= 0 and right + 1 < len(text1) and p1 <= p2 and base1[p1] == base2[p2]:
        if p1 + left - 1 < right:
            left -= 1
        else:
            mid = 0
        if p2 < len(text2) - mid - 1:
            p2 -= 1
            right += mid
    if p1 > p2 and p1 not in [len(base1)]:
        return 1 + matching_length(base.substr(p1+p1, len(base1) - p1 - 1))
    return 1 + matching_length(base1[p1:end], base2[p2:end])

