from bisect import bisect_left

def parse_data(data):
    player_positions = {}
    for i, t in enumerate(data):
        if t != 0:
            player_positions[i] = t
    return player_positions

def simulate_game(player_positions, rounds):
    current_turn = 0
    while current_turn < rounds:
        subtweets = [0] * len(player_positions)
        for player in sorted(player_positions.keys()):
            if current_turn >= player_positions[player]:
                subtweets[player] = 1
        if all(subtweets):
            break
        for player in sorted(player_positions.keys()):
            if current_turn + rounds - 1 >= player_positions[player]:
                current_turn += rounds - 1
                if len(subtweets) == 1:
                    subtweets = [subtweets[0]]
                break
        print(subtweets)
        output = ""
        for result in subtweets:
            output += "0" if result else "1"
        print(output)
        with open("output.txt", "a") as file:
            file.write(output + '\n')
        data = [rounds * i for i in subtweets]
        print(data)

if __name__ == "__main__":
    n = int(input())
    data = list(map(int, input().split()))
    player_positions = parse_data(data)
    simulate_game(player_positions, n)
