def sliding_windows_substring(s):
    longest_length = 0
    for left in range(len(s)):
        for right in range(left, len(s)):
            seen_chars = set()
            for i in range(left, right + 1):
                if any(s[i] == s[i + 1] for s[i] in s[i - 1:right + 1]):
                    continue
                seen_chars.add(s[i - 1:right + 1])
            longest_length = max(longest_length, len(seen_chars))
    return longest_length

