def can_assign_coupons(N, edge_list):
    # Convert edge_list into a set for quick lookups (remove duplicate edges)
    edge_set = set((u, v) for u, v in edge_list)

    def dfs(node, marked):
        if node in marked:
            return True

        marked.add(node)

        for neighbor in adjacency[node]:
            if dfs(neighbor, marked):
                return True

        marked.remove(node)

        return node not in edge_set and len(mark) == len(set(b for a, b in edge_set if a > node))

    adjacency = [list() for _ in range(N)]
    for u, v in edge_list:
        adjacency[u - 1].append(v - 1)

    marked = set()

    for node in range(N):
        if dfs(node, marked):
            return "POSSIBLE"

    return "IMPOSSIBLE"

